//! Old exports of glibc 2.43 (version GLIBC_2.2.5 / 2.4) that need code and not just a jump (the jumps are in compat_abi.rs,
//! generated by hdrgen oldabi): the `stat` family that glibc before 2.33 compiled `stat`, `fstat`, `lstat`, `fstatat`
//! and `mknod` calls into, `__libc_freeres` and friends. Programs built on an old glibc import them (the official Rust
//! toolchain's cargo, rustc and libLLVM, Electron, Chromium, vsce-sign, ...), and fail to start without them.
//! The behaviour follows glibc 2.43's sysdeps/unix/sysv/linux/{xstat,fxstat,lxstat,fxstatat,xmknod,xmknodat}*.c on x86-64
//! (read as reference; the code is Rust): the version argument must be `_STAT_VER_KERNEL` (0) or `_STAT_VER_LINUX` (1), the
//! `struct stat` of both is the kernel's, and the result is the plain system call's. `__xmknod` wants `_MKNOD_VER` 0.
use core::ffi::{c_char, c_int, c_void};
use rusty_libc_core::{errno, syscall};

const EINVAL: i32 = 22;
const SYS_STAT: usize = 4;
const SYS_FSTAT: usize = 5;
const SYS_LSTAT: usize = 6;
const SYS_NEWFSTATAT: usize = 262;
const SYS_MKNOD: usize = 133;
const SYS_MKNODAT: usize = 259;
const SYS_GETPGID: usize = 121;

fn ver_ok(vers: c_int) -> bool {
    vers == 0 || vers == 1
}

/// System call `nr` with C's convention: -1 and errno on failure.
///
/// # Safety
/// The arguments are valid for system call `nr`.
unsafe fn call(nr: usize, a: usize, b: usize, c: usize, d: usize) -> c_int {
    // SAFETY: the arguments are valid for `nr` (forwarded contract).
    let r = unsafe { syscall::syscall4(nr, a, b, c, d) };
    match syscall::check(r) {
        Ok(v) => v as c_int,
        Err(e) => {
            errno::set(e.0);
            -1
        }
    }
}

fn einval() -> c_int {
    errno::set(EINVAL);
    -1
}

/// `__xstat(vers, path, buf)`: stat.
///
/// # Safety
/// `path` is a C string, `buf` points to a `struct stat`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn __xstat(vers: c_int, path: *const c_char, buf: *mut c_void) -> c_int {
    if !ver_ok(vers) {
        return einval();
    }
    // SAFETY: stat(2) reads the C string `path` and writes a `struct stat` to `buf` (the contract).
    unsafe { call(SYS_STAT, path as usize, buf as usize, 0, 0) }
}

/// `__xstat64`: the same as `__xstat` (x86-64 has one `struct stat`).
///
/// # Safety
/// As `__xstat`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn __xstat64(vers: c_int, path: *const c_char, buf: *mut c_void) -> c_int {
    // SAFETY: the same contract.
    unsafe { __xstat(vers, path, buf) }
}

/// `__lxstat(vers, path, buf)`: lstat.
///
/// # Safety
/// As `__xstat`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn __lxstat(vers: c_int, path: *const c_char, buf: *mut c_void) -> c_int {
    if !ver_ok(vers) {
        return einval();
    }
    // SAFETY: lstat(2) reads the C string `path` and writes a `struct stat` to `buf` (the contract).
    unsafe { call(SYS_LSTAT, path as usize, buf as usize, 0, 0) }
}

/// `__lxstat64`: the same as `__lxstat`.
///
/// # Safety
/// As `__xstat`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn __lxstat64(vers: c_int, path: *const c_char, buf: *mut c_void) -> c_int {
    // SAFETY: the same contract.
    unsafe { __lxstat(vers, path, buf) }
}

/// `__fxstat(vers, fd, buf)`: fstat.
///
/// # Safety
/// `buf` points to a `struct stat`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn __fxstat(vers: c_int, fd: c_int, buf: *mut c_void) -> c_int {
    if !ver_ok(vers) {
        return einval();
    }
    // SAFETY: fstat(2) writes a `struct stat` to `buf` (the contract).
    unsafe { call(SYS_FSTAT, fd as usize, buf as usize, 0, 0) }
}

/// `__fxstat64`: the same as `__fxstat`.
///
/// # Safety
/// As `__fxstat`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn __fxstat64(vers: c_int, fd: c_int, buf: *mut c_void) -> c_int {
    // SAFETY: the same contract.
    unsafe { __fxstat(vers, fd, buf) }
}

/// `__fxstatat(vers, dirfd, path, buf, flags)`: fstatat.
///
/// # Safety
/// As `__xstat`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn __fxstatat(vers: c_int, dirfd: c_int, path: *const c_char, buf: *mut c_void, flags: c_int) -> c_int {
    if !ver_ok(vers) {
        return einval();
    }
    // SAFETY: newfstatat(2) reads the C string `path` and writes a `struct stat` to `buf` (the contract).
    unsafe { call(SYS_NEWFSTATAT, dirfd as isize as usize, path as usize, buf as usize, flags as isize as usize) }
}

/// `__fxstatat64`: the same as `__fxstatat`.
///
/// # Safety
/// As `__xstat`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn __fxstatat64(vers: c_int, dirfd: c_int, path: *const c_char, buf: *mut c_void, flags: c_int) -> c_int {
    // SAFETY: the same contract.
    unsafe { __fxstatat(vers, dirfd, path, buf, flags) }
}

/// `__xmknod(vers, path, mode, dev)`: mknod with the device number passed by address.
///
/// # Safety
/// `path` is a C string, `dev` points to a `dev_t`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn __xmknod(vers: c_int, path: *const c_char, mode: u32, dev: *const u64) -> c_int {
    if vers != 0 {
        return einval();
    }
    // SAFETY: `dev` points to a `dev_t` (the contract).
    let dev = unsafe { *dev };
    // SAFETY: mknod(2) reads the C string `path` (the contract).
    unsafe { call(SYS_MKNOD, path as usize, mode as usize, dev as usize, 0) }
}

/// `__xmknodat(vers, dirfd, path, mode, dev)`: mknodat with the device number passed by address.
///
/// # Safety
/// As `__xmknod`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn __xmknodat(vers: c_int, dirfd: c_int, path: *const c_char, mode: u32, dev: *const u64) -> c_int {
    if vers != 0 {
        return einval();
    }
    // SAFETY: `dev` points to a `dev_t` (the contract).
    let dev = unsafe { *dev };
    // SAFETY: mknodat(2) reads the C string `path` (the contract).
    unsafe { call(SYS_MKNODAT, dirfd as isize as usize, path as usize, mode as usize, dev as usize) }
}

/// `__libc_freeres()`: release the library's memory for leak checkers (valgrind calls it at exit): the stdio buffers.
#[unsafe(no_mangle)]
pub extern "C" fn __libc_freeres() {
    rusty_libc_stdio::file::freeres()
}

/// `__libc_init_first(argc, argv, envp)`: called by the startup code of very old programs; this library starts itself.
#[unsafe(no_mangle)]
pub extern "C" fn __libc_init_first(_argc: c_int, _argv: *mut *mut c_char, _envp: *mut *mut c_char) {}

/// `__libc_sa_len(family)`: the size of a `struct sockaddr` of an address family (0 if unknown), used by old resolver code.
#[unsafe(no_mangle)]
pub extern "C" fn __libc_sa_len(family: u16) -> c_int {
    match family {
        1 => 110, // AF_UNIX: sockaddr_un
        2 => 16,  // AF_INET
        10 => 28, // AF_INET6
        16 => 12, // AF_NETLINK
        17 => 20, // AF_PACKET: sockaddr_ll
        _ => 0,
    }
}

/// `__bsd_getpgrp(pid)`: the BSD getpgrp, which takes a process id: getpgid.
#[unsafe(no_mangle)]
pub extern "C" fn __bsd_getpgrp(pid: c_int) -> c_int {
    // SAFETY: getpgid(2) takes a plain value.
    unsafe { call(SYS_GETPGID, pid as usize, 0, 0, 0) }
}
